    'today': {TODAY},
    'last_7_days': {TODAY - timedelta(days=i) for i in range(7)},
    'last_30_days': {TODAY - timedelta(days=i) for i in range(30)},
}
month_start = date(2025, 8, 1)
month_to_date = {
    month_start + timedelta(days=i)
    for i in range((TODAY - month_start).days + 1)
}
period_dates['month_to_date'] = month_to_date

counts = {
    period: {severity: 0 for severity in SEVERITIES}
    for period in ('today', 'last_7_days', 'last_30_days', 'month_to_date')
}
total_counts = {severity: 0 for severity in SEVERITIES}

severity_pattern = re.compile(r'\[(ERROR|WARNING|INFO)\]')

for path in sorted(LOG_DIR.glob('*.log')):
    log_date = date.fromisoformat(path.name.split('_', 1)[0])
    for line in path.read_text(encoding='utf-8').splitlines():
        match = severity_pattern.search(line)
        if not match:
            continue

        severity = match.group(1)
        total_counts[severity] += 1

        for period, dates in period_dates.items():
            if log_date in dates:
                counts[period][severity] += 1
                break

with OUTPUT.open('w', encoding='utf-8', newline='') as output:
    output.write('period,severity,count\n')
    for period in ('today', 'last_7_days', 'last_30_days', 'month_to_date'):
        for severity in SEVERITIES:
            output.write(f'{period},{severity},{counts[period][severity]}\n')
    for severity in SEVERITIES:
        output.write(f'total,{severity},{total_counts[severity]}\n')
