from pathlib import Path
from datetime import date, timedelta
import re

TODAY = date(2025, 8, 12)
SEVERITIES = ('ERROR', 'WARNING', 'INFO')
PERIODS = (
    ('today', TODAY, TODAY),
    ('last_7_days', TODAY - timedelta(days=6), TODAY),
    ('last_30_days', TODAY - timedelta(days=29), TODAY),
    ('month_to_date', date(2025, 8, 1), TODAY),
)

counts = {period: {severity: 0 for severity in SEVERITIES} for period, _, _ in PERIODS}
totals = {severity: 0 for severity in SEVERITIES}
pattern = re.compile(r'\[(ERROR|WARNING|INFO)\]')

for path in sorted(Path('/app/logs').glob('*.log')):
    log_date = date.fromisoformat(path.name.split('_', 1)[0])
    for line in path.read_text(encoding='utf-8').splitlines():
        match = pattern.search(line)
        if not match:
            continue
        severity = match.group(1)
        totals[severity] += 1
        for period, start, end in PERIODS:
            if start <= log_date <= end:
                counts[period][severity] += 1

with Path('/app/summary.csv').open('w', encoding='utf-8', newline='') as output:
    output.write('period,severity,count\n')
    for period, _, _ in PERIODS:
        for severity in SEVERITIES:
            output.write(f'{period},{severity},{counts[period][severity]}\n')
    for severity in SEVERITIES:
        output.write(f'total,{severity},{totals[severity]}\n')
